// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        bool migrateOk;
        vm.prank(actor);
        try c.migrateTo(actor) { migrateOk = true; } catch { migrateOk = false; }

        bool isCreator = (actor == address(this));
        assertTrue(migrateOk == isCreator);
    }
}
